CREATE TABLE IF NOT EXISTS acp_plan_index_ready (id INTEGER PRIMARY KEY CHECK(id=1)) STRICT;
DELETE FROM acp_plan_index_ready WHERE NOT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='acp_plan_index');
CREATE TABLE IF NOT EXISTS acp_plan_index (
source TEXT NOT NULL,schedule_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
enabled INTEGER NOT NULL,metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json) AND length(CAST(metadata_json AS BLOB))<=16384),
PRIMARY KEY(source,schedule_id), FOREIGN KEY(source,schedule_id) REFERENCES acp_scheduled_plans(source,schedule_id) ON DELETE CASCADE) STRICT;
CREATE INDEX IF NOT EXISTS acp_plan_due_time ON acp_plan_state(source,next_run_at,schedule_id) WHERE next_run_at IS NOT NULL;
CREATE TRIGGER IF NOT EXISTS acp_plan_index_insert AFTER INSERT ON acp_scheduled_plans BEGIN INSERT INTO acp_plan_index (source,schedule_id,revision,enabled,metadata_json) VALUES (NEW.source,NEW.schedule_id,NEW.revision,CASE WHEN json_type(NEW.definition_json,'$.enabled')='true' THEN 1 ELSE 0 END,json_object('name',json_extract(NEW.definition_json,'$.name'),'projectId',json_extract(NEW.definition_json,'$.projectId'),'engine',json_extract(NEW.definition_json,'$.engine'),'enabled',json(NEW.definition_json->'$.enabled'),'schedule',json(NEW.definition_json->'$.schedule'))) ON CONFLICT(source,schedule_id) DO UPDATE SET revision=excluded.revision,enabled=excluded.enabled,metadata_json=excluded.metadata_json; END;
CREATE TRIGGER IF NOT EXISTS acp_plan_index_update AFTER UPDATE ON acp_scheduled_plans BEGIN INSERT INTO acp_plan_index (source,schedule_id,revision,enabled,metadata_json) VALUES (NEW.source,NEW.schedule_id,NEW.revision,CASE WHEN json_type(NEW.definition_json,'$.enabled')='true' THEN 1 ELSE 0 END,json_object('name',json_extract(NEW.definition_json,'$.name'),'projectId',json_extract(NEW.definition_json,'$.projectId'),'engine',json_extract(NEW.definition_json,'$.engine'),'enabled',json(NEW.definition_json->'$.enabled'),'schedule',json(NEW.definition_json->'$.schedule'))) ON CONFLICT(source,schedule_id) DO UPDATE SET revision=excluded.revision,enabled=excluded.enabled,metadata_json=excluded.metadata_json; END;
INSERT INTO acp_plan_index SELECT p.source,p.schedule_id,p.revision,CASE WHEN json_type(p.definition_json,'$.enabled')='true' THEN 1 ELSE 0 END,json_object('name',json_extract(p.definition_json,'$.name'),'projectId',json_extract(p.definition_json,'$.projectId'),'engine',json_extract(p.definition_json,'$.engine'),'enabled',json(p.definition_json->'$.enabled'),'schedule',json(p.definition_json->'$.schedule')) FROM acp_scheduled_plans p WHERE NOT EXISTS(SELECT 1 FROM acp_plan_index_ready WHERE id=1) AND NOT EXISTS(SELECT 1 FROM acp_plan_index i WHERE i.source=p.source AND i.schedule_id=p.schedule_id AND i.revision=p.revision) ON CONFLICT(source,schedule_id) DO UPDATE SET revision=excluded.revision,enabled=excluded.enabled,metadata_json=excluded.metadata_json;
INSERT INTO acp_plan_index_ready (id) VALUES (1) ON CONFLICT DO NOTHING;
